            ))
          )}
        </section>
      )}

      <ResponsiveGrid
        className={mode === 'edit' ? 'dashboard__grid dashboard__grid--edit' : 'dashboard__grid'}
        layouts={layouts}
        breakpoints={breakpoints}
        cols={columns}
        rowHeight={28}
